# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ATP (ADENOZİN TRİFOSFAT) MOLEKÜLÜNÜN YAPISI</text>\n  <rect x="30" y="65" width="140" height="80" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="100" y="100" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">ADENİN</text>\n  <text x="100" y="120" text-anchor="middle" font-size="11" fill="#1e3a8a">(Azotlu Organik Baz)</text>\n  <line x1="170" y1="105" x2="215" y2="105" stroke="#dc2626" stroke-width="3"/>\n  <text x="192" y="95" text-anchor="middle" font-size="10" font-weight="bold" fill="#dc2626">Glikozit</text>\n  <polygon points="265,60 320,90 300,145 230,145 210,90" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="265" y="108" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">RİBOZ</text>\n  <text x="265" y="126" text-anchor="middle" font-size="10" fill="#14532d">(5C Pentoz Şekeri)</text>\n  <line x1="320" y1="105" x2="365" y2="105" stroke="#9333ea" stroke-width="3"/>\n  <text x="342" y="95" text-anchor="middle" font-size="10" font-weight="bold" fill="#9333ea">Fosfoester</text>\n  <circle cx="400" cy="105" r="32" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="400" y="110" text-anchor="middle" font-size="14" font-weight="bold" fill="#92400e">P₁</text>\n  <text x="452" y="112" text-anchor="middle" font-size="22" font-weight="bold" fill="#dc2626">~</text>\n  <circle cx="505" cy="105" r="32" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="505" y="110" text-anchor="middle" font-size="14" font-weight="bold" fill="#92400e">P₂</text>\n  <text x="557" y="112" text-anchor="middle" font-size="22" font-weight="bold" fill="#dc2626">~</text>\n  <circle cx="610" cy="105" r="32" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="610" y="110" text-anchor="middle" font-size="14" font-weight="bold" fill="#92400e">P₃</text>\n  <text x="505" y="55" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">Yüksek Enerjili Fosfat Bağları (~)</text>\n  <rect x="30" y="165" width="290" height="32" rx="6" fill="#eff6ff" stroke="#60a5fa"/>\n  <text x="175" y="185" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Adenin + Riboz = Adenozin (Nükleozit)</text>\n  <rect x="30" y="205" width="405" height="32" rx="6" fill="#f0fdf4" stroke="#4ade80"/>\n  <text x="232" y="225" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Adenozin + 1P = AMP · + 2P = ADP · + 3P = ATP</text>\n  <rect x="450" y="165" width="220" height="72" rx="8" fill="#fef2f2" stroke="#f87171"/>\n  <text x="560" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">ATP Hücre İçi Üretilir ve Tüketilir</text>\n  <text x="560" y="210" text-anchor="middle" font-size="11" fill="#7f1d1d">Depolanamaz, hücreden hücreye</text>\n  <text x="560" y="226" text-anchor="middle" font-size="11" fill="#7f1d1d">aktarılamaz!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FOSFORİLASYON – DEFOSFORİLASYON DÖNGÜSÜ VE ÇEŞİTLERİ</text>\n  <rect x="25" y="48" width="310" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Enerji Dönüşüm Döngüsü</text>\n  <rect x="55" y="90" width="95" height="42" rx="8" fill="#dbeafe" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="102" y="116" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">ADP + Pᵢ</text>\n  <rect x="210" y="90" width="95" height="42" rx="8" fill="#dcfce7" stroke="#15803d" stroke-width="1.5"/>\n  <text x="257" y="116" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">ATP + H₂O</text>\n  <path d="M 152 100 L 206 100" stroke="#16a34a" stroke-width="2.5"/>\n  <text x="180" y="93" text-anchor="middle" font-size="10" font-weight="bold" fill="#16a34a">Fosforilasyon</text>\n  <path d="M 206 122 L 152 122" stroke="#dc2626" stroke-width="2.5"/>\n  <text x="180" y="136" text-anchor="middle" font-size="10" font-weight="bold" fill="#dc2626">Defosforilasyon</text>\n  <text x="42" y="164" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Ekzergonik (Enerji Veren):</tspan> Hücresel solunum,</text>\n  <text x="52" y="180" font-size="11" fill="#1e3a8a">fermantasyon (ATP sentezini sağlar).</text>\n  <text x="42" y="204" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Endergonik (Enerji Alan):</tspan> Biyosentez, aktif</text>\n  <text x="52" y="220" font-size="11" fill="#1e3a8a">taşıma, kas kasılması, sinirsel iletim.</text>\n  <rect x="355" y="48" width="320" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="515" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Fosforilasyon (ATP Üretim) Çeşitleri</text>\n  <rect x="372" y="84" width="286" height="44" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="382" y="102" font-size="11" font-weight="bold" fill="#b45309">1. Substrat Düzeyinde Fosforilasyon (SDF)</text>\n  <text x="382" y="119" font-size="10.5" fill="#78350f">Glikoliz ve Krebs döngüsü; TÜM canlılarda ortaktır.</text>\n  <rect x="372" y="136" width="286" height="44" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="382" y="154" font-size="11" font-weight="bold" fill="#b45309">2. Oksidatif Fosforilasyon (OF)</text>\n  <text x="382" y="171" font-size="10.5" fill="#78350f">ETS\'de elektron aktarımıyla (O₂\'li/O₂\'siz solunum, kemosentez).</text>\n  <rect x="372" y="188" width="286" height="44" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="382" y="206" font-size="11" font-weight="bold" fill="#b45309">3. Fotofosforilasyon (FF)</text>\n  <text x="382" y="223" font-size="10.5" fill="#78350f">Klorofil ve ışık enerjisi yardımıyla ETS üzerinden ATP sentezi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KLOROPLASTIN YAPISI VE FOTOSENTEZ PİGMENTLERİ</text>\n  <rect x="25" y="46" width="330" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="190" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Kloroplast Organeli Şeması</text>\n  <ellipse cx="190" cy="142" rx="135" ry="62" fill="#bbf7d0" stroke="#15803d" stroke-width="3"/>\n  <ellipse cx="190" cy="142" rx="125" ry="54" fill="#f0fdf4" stroke="#22c55e" stroke-width="2"/>\n  <rect x="105" y="112" width="44" height="12" rx="5" fill="#16a34a"/><rect x="105" y="126" width="44" height="12" rx="5" fill="#16a34a"/><rect x="105" y="140" width="44" height="12" rx="5" fill="#16a34a"/><rect x="105" y="154" width="44" height="12" rx="5" fill="#16a34a"/>\n  <rect x="215" y="118" width="44" height="12" rx="5" fill="#16a34a"/><rect x="215" y="132" width="44" height="12" rx="5" fill="#16a34a"/><rect x="215" y="146" width="44" height="12" rx="5" fill="#16a34a"/>\n  <line x1="149" y1="132" x2="215" y2="138" stroke="#15803d" stroke-width="3"/>\n  <text x="182" y="112" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">Stroma sıvısı</text>\n  <text x="127" y="182" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Granum (Tilakoit)</text>\n  <text x="245" y="176" text-anchor="middle" font-size="10" fill="#14532d">DNA, RNA, Ribozom</text>\n  <text x="190" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Tilakoit zar: Işığa bağımlı · Stroma: Işıktan bağımsız</text>\n  <rect x="370" y="46" width="305" height="196" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="522" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Fotosentez Pigmentleri ve Işık</text>\n  <text x="386" y="94" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Klorofil (a, b):</tspan> C, H, O, N ve merkezde <tspan font-weight="bold">Mg</tspan></text>\n  <text x="396" y="110" font-size="11" fill="#581c87">atomu içerir (sentezi için Fe kofaktörü gerekir).</text>\n  <text x="386" y="132" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Soğurulan Işık:</tspan> En çok <tspan font-weight="bold">mor ve kırmızı</tspan> dalga</text>\n  <text x="396" y="148" font-size="11" fill="#581c87">boylarını soğurur; yeşil ışığı çoğunlukla yansıtır.</text>\n  <text x="386" y="170" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Karotenoitler:</tspan> Karoten (turuncu), ksantofil</text>\n  <text x="396" y="186" font-size="11" fill="#581c87">(sarı), likopen (kırmızı); fazla ışığı sönümler.</text>\n  <rect x="386" y="198" width="272" height="32" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="522" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Fotosentez Hızı: Mor-Mavi ve Kırmızıda Yüksek!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
